import { expect, expectStatus, test, uniqueName, type Document, type Vendor } from "../../fixtures";

test(
  "approving the replacement approves a vendor whose other documents were already approved",
  { tag: "@LIF-06" },
  async ({ apiAs, factory }) => {
    // Arrange: a vendor in review; approve its insurance certificate and contract, reject its W-9,
    // then have the member upload a replacement W-9, wait for extraction, and resubmit.
    const { vendor, extractions } = await factory.vendorInReview({ name: uniqueName("LIF-06 Vendor") });
    const reviewer = await apiAs("reviewer");
    const member = await apiAs("member");

    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      }),
      200,
    );

    const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
    await expect
      .poll(
        async () => {
          const documents = await expectStatus<Document[]>(
            await member.get(`/api/vendors/${vendor.id}/documents`),
            200,
          );
          return documents.find((d) => d.id === replacement.id)?.status;
        },
        { message: "replacement W-9 finishes extraction", timeout: 30_000 },
      )
      .toBe("extracted");
    await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
    const replacementExtraction = await factory.extraction(replacement.id, "member");
    expect(replacementExtraction.status, "replacement W-9 awaits review").toBe("pending_review");

    // Act: the reviewer approves the replacement W-9, the only extraction still pending.
    const decision = await expectStatus(
      await reviewer.post(`/api/extractions/${replacementExtraction.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );

    // Assert: the extraction is approved, the vendor is approved, and the audit trail records it.
    expect(decision.status).toBe("approved");
    const stored = await expectStatus<Vendor>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("approved");
    const trail = await expectStatus<{ items: { action: string }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(trail.items.map((event) => event.action)).toContain("vendor.approved");
  },
);
